#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define MLX90614_ADDR 0x5a
#define I2C_DEVICE "/dev/i2c-1"
#define MEASUREMENT_REG 0x00
#define ERROR_VALUE -1000.0f

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit value from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MLX90614_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t raw;
        if (i2c_read_reg16(fd, MEASUREMENT_REG, &raw) == 0) {
            float temperature = (float)raw * 0.02f - 273.15f;
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }
        sleep(5);
    }

    close(fd);
    return EXIT_SUCCESS;
}

