static struct gpiod_line *line4 = NULL;
static struct gpiod_line *line17 = NULL;
static volatile sig_atomic_t keep_running = 1;

static void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

static void cleanup(void) {
    if (line4) {
        gpiod_line_release(line4);
        line4 = NULL;
    }
    if (line17) {
        gpiod_line_release(line17);
        line17 = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

