    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line4 = gpiod_chip_get_line(chip, GPIO_LINE_4);
    if (!line4) {
        perror("gpiod_chip_get_line(4)");
        cleanup();
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_LINE_17);
    if (!line17) {
        perror("gpiod_chip_get_line(17)");
        cleanup();
        return EXIT_FAILURE;
    }

