        perror("gpiod_line_request_output(4)");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line17, "gpio-control", 0) < 0) {
        perror("gpiod_line_request_output(17)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("GPIO 4 (BCM %d) and GPIO 17 (BCM %d) controlled by libgpiod.\n", GPIO_LINE_4, GPIO_LINE_17);
    printf("Press Ctrl+C to exit.\n");

    while (keep_running) {
        int val4 = gpiod_line_get_value(line4);
        int val17 = gpiod_line_get_value(line17);

        if (val4 < 0 || val17 < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        printf("GPIO 4: %d, GPIO 17: %d\n", val4, val17);
        fflush(stdout);

        sleep(1);
    }

    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
