/*
 * Measure distance in cm. Returns -1.0 on timeout or error.
 * Uses a 2-stage echo pulse:
 *   1. Send 10 us trigger pulse.
 *   2. Wait for echo rising edge.
 *   3. Measure pulse width in microseconds.
 *   4. Convert to cm: speed_of_sound * time / 2.
 */
static float measure_distance(struct gpiod_line *trigger, struct gpiod_line *echo)
{
    int ret;

    /* Ensure trigger starts low */
    ret = gpiod_line_set_value(trigger, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: failed to set trigger low: %s\n", strerror(errno));
        return -1.0f;
    }
    usleep(2);

    /* Send 10 us trigger pulse */
    ret = gpiod_line_set_value(trigger, 1);
    if (ret < 0) {
        fprintf(stderr, "Error: failed to set trigger high: %s\n", strerror(errno));
        return -1.0f;
    }
    usleep(10);
    ret = gpiod_line_set_value(trigger, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: failed to set trigger low: %s\n", strerror(errno));
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout if no object) */
    int val = gpiod_line_get_value(echo);
    if (val < 0) {
        fprintf(stderr, "Error: failed to read echo: %s\n", strerror(errno));
        return -1.0f;
    }
    uint32_t start_tick = 0;
    for (int i = 0; i < TIMEOUT_US; i++) {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            fprintf(stderr, "Error: failed to read echo: %s\n", strerror(errno));
            return -1.0f;
        }
        if (val == 1) {
            start_tick = gpiod_line_get_value_tick(echo);
            break;
        }
        usleep(POLL_US);
    }
    if (start_tick == 0) {
        fprintf(stderr, "Error: echo rising edge timeout (no object)\n");
        return -1.0f;
    }

    /* Wait for echo falling edge (timeout if object too far) */
    uint32_t end_tick = 0;
    for (int i = 0; i < TIMEOUT_US; i++) {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            fprintf(stderr, "Error: failed to read echo: %s\n", strerror(errno));
            return -1.0f;
        }
        if (val == 0) {
            end_tick = gpiod_line_get_value_tick(echo);
            break;
        }
        usleep(POLL_US);
    }
    if (end_tick == 0) {
        fprintf(stderr, "Error: echo falling edge timeout (object too far)\n");
        return -1.0f;
    }

    uint32_t pulse_us = end_tick - start_tick;
    float distance = (float)pulse_us * 0.0343f / 2.0f;

    /* Sanity range check */
    if (distance < 2.0f || distance > 400.0f) {
        fprintf(stderr, "Warning: distance %.2f cm out of range (2-400 cm)\n", distance);
        return -1.0f;
    }

    return distance;
}

