#include <errno.h>
#include <string.h>
#include <signal.h>

#define SI7021_ADDR 0x40
#define I2C_DEV "/dev/i2c-1"
#define MEASURE_CMD 0xF5
#define READ_MEASURE_CMD 0xE0
#define MEASURE_DELAY_US 18000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_measurement(int fd, uint16_t *temperature, uint16_t *humidity) {
    if (i2c_write_byte(fd, MEASURE_CMD) < 0) {
        return -1;
    }
    usleep(MEASURE_DELAY_US);

    uint8_t buf[6];
    if (i2c_read_bytes(fd, buf, 6) < 0) {
        return -1;
    }

    uint16_t raw_temp = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t raw_hum = ((uint16_t)buf[3] << 8) | buf[4];

    if ((raw_temp & 0xFC00) != 0x8000) {
        fprintf(stderr, "Temperature data invalid: 0x%04X\n", raw_temp);
        return -1;
    }
    if ((raw_hum & 0xFC00) != 0x8000) {
        fprintf(stderr, "Humidity data invalid: 0x%04X\n", raw_hum);
        return -1;
    }

    *temperature = raw_temp & 0x3FFF;
    *humidity = raw_hum & 0x3FFF;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI7021_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    printf("SI7021 sensor reader started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t temperature, humidity;
        if (read_measurement(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   (float)temperature * 175.72 / 65536.0 - 46.85,
                   (float)humidity * 125.0 / 65536.0 - 6.0);
        } else {
            fprintf(stderr, "Failed to read measurement.\n");
        }
        sleep(5);
    }

    printf("\nExiting cleanly.\n");
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_read_conversion(int fd, int16_t *raw) {
    uint16_t config = 0x8483; /* AIN0 single-ended, +/-4.096V, 128 SPS, continuous */
    if (i2c_write_reg16(fd, ADS1115_REG_CONFIG, config) < 0) {
        return -1;
    }
    usleep(10000); /* 10 ms conversion time */
    uint16_t val;
    if (i2c_read_reg16(fd, ADS1115_REG_CONVERSION, &val) < 0) {
        return -1;
    }
    *raw = (int16_t)val;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    printf("ADS1115 ADC reader started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t raw;
        if (ads1115_read_conversion(fd, &raw) < 0) {
            fprintf(stderr, "ADC read failed; continuing.\n");
        } else {
            printf("Raw ADC value: %d\n", raw);
        }
        sleep(1);
    }

    printf("\nExiting gracefully...\n");
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_PINS 6
#define CONSUMER "gpio-test"

static const unsigned int pins[NUM_PINS] = {8, 9, 10, 11, 23, 24};
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_PINS];
static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("Starting %d cycles of digital output on GPIO 8, GPIO 9, GPIO 10, GPIO 11, GPIO 23, GPIO 24...\n", NUM_PINS);
    fflush(stdout);

    for (int cycle = 0; cycle < 256 && keep_running; cycle++) {
        for (int i = 0; i < NUM_PINS; i++) {
            if (gpiod_line_set_value(lines[i], (cycle >> (7 - i)) & 1) < 0) {
                fprintf(stderr, "Failed to set GPIO line %u\n", pins[i]);
                cleanup();
                return EXIT_FAILURE;
            }
        }
        usleep(10000);
    }

    cleanup();
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

