        perror("gpiod_line_request_output line2");
        cleanup_and_exit(0);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(line3, "gpio-control", 0) < 0) {
        perror("gpiod_line_request_output line3");
        cleanup_and_exit(0);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int val1 = gpiod_line_get_value(line1);
        int val2 = gpiod_line_get_value(line2);
