#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_17 17
#define GPIO_18 18
#define GPIO_27 27
#define POLL_INTERVAL_US 500000  /* 0.05 seconds */

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the lines */
    lines[0] = gpiod_chip_get_line(chip, GPIO_17);
    lines[1] = gpiod_chip_get_line(chip, GPIO_18);
    lines[2] = gpiod_chip_get_line(chip, GPIO_27);
    if (!lines[0] || !lines[1] || !lines[2]) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request each line as output, initial value LOW */
    for (int i = 0; i < 3; i++) {
        if (gpiod_line_request_output(lines[i], "gpio-control", 0) < 0) {
            perror("gpiod_line_request_output");
            goto cleanup;
        }
    }

    printf("GPIO control started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (keep_running) {
        for (int i = 0; i < 3; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                perror("gpiod_line_get_value");
                goto cleanup;
            }
            printf("GPIO %d: %d\n", i + 17, val);
        }
        fflush(stdout);
        usleep(POLL_INTERVAL_US);
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

