#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define CONSUMER    "hcsr04"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int trigger_sensor(struct gpiod_line *trigger)
{
    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    usleep(2);
    if (gpiod_line_set_value(trigger, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high: %s\n", strerror(errno));
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_echo_pulse(struct gpiod_line *echo)
{
    int val;
    int timeout = 0;

    /* Wait for echo to go high (start of pulse) */
    do {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            fprintf(stderr, "Error: failed to read echo: %s\n", strerror(errno));
            return -1;
        }
        if (++timeout > 10000) {
            fprintf(stderr, "Error: echo start timeout\n");
            return -1;
        }
        usleep(1);
    } while (val == 0);

    long start_tick = 0;
    timeout = 0;
    do {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            fprintf(stderr, "Error: failed to read echo: %s\n", strerror(errno));
            return -1;
        }
        if (val == 1) {
            start_tick = (long)clock();
            break;
        }
        if (++timeout > 10000) {
            fprintf(stderr, "Error: echo end timeout\n");
            return -1;
        }
        usleep(1);
    } while (1);

    /* Wait for echo to go low (end of pulse) */
    timeout = 0;
    do {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            fprintf(stderr, "Error: failed to read echo: %s\n", strerror(errno));
            return -1;
        }
        if (val == 0) {
            break;
        }
        if (++timeout > 10000) {
            fprintf(stderr, "Error: echo end timeout\n");
            return -1;
        }
        usleep(1);
    } while (1);

    long end_tick = (long)clock();
    long pulse_duration = end_tick - start_tick;
    long distance_cm = (pulse_duration * 34300) / 2000000;

    if (distance_cm < 2 || distance_cm > 400) {
        fprintf(stderr, "Warning: distance out of range: %ld cm\n", distance_cm);
        return -1;
    }

    return (int)distance_cm;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean exit */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the trigger line */
    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        fprintf(stderr, "Error: failed to get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    /* Get the echo line */
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Error: failed to get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request trigger line as output, initial value low */
    if (gpiod_line_request_output(trigger, CONSUMER, 0) < 0) {
        fprintf(stderr, "Error: failed to request trigger line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request echo line as input */
    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        fprintf(stderr, "Error: failed to request echo line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        if (trigger_sensor(trigger) < 0) {
            fprintf(stderr, "Error: trigger failed, skipping cycle\n");
            sleep(1);
            continue;
        }

        int distance = read_echo_pulse(echo);
        if (distance < 0) {
            fprintf(stderr, "Error: echo read failed, skipping cycle\n");
            sleep(1);
            continue;
        }

        printf("Distance: %d cm\n", distance);
        sleep(1);
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (trigger) {
        gpiod_line_release(trigger);
    }
    if (echo) {
        gpiod_line_release(echo);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

