#define DHT11_PIN 4
#define DHT11_TIMEOUT_US 100000
#define DHT11_MAX_RETRIES 5

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
