/*
 * Read 40 bits from the DHT11.
 * Returns 0 on success, -1 on timeout, -2 on checksum error.
 */
static int read_dht11(struct gpiod_line *line, uint8_t data[5]) {
    uint8_t laststate = 1;
    uint8_t counter = 0;
    uint8_t j = 0;

    /* Send start signal: pull low for >= 1ms, then high for 30us */
    if (gpiod_line_request_output(line, "dht11", 0) < 0) {
        fprintf(stderr, "Failed to request line as output: %s\n", strerror(errno));
        return -1;
    }
    gpiod_line_set_value(line, 0);
    usleep(1000);
    gpiod_line_set_value(line, 1);
    usleep(30);

    /* Switch to input with pull-up */
    if (gpiod_line_request_input_flags(line, "dht11", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request line as input: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for DHT11 response: low for ~80us, high for ~80us */
    int timeout = DHT11_TIMEOUT_US;
    while (gpiod_line_get_value(line) == 1) {
        if (--timeout <= 0) return -1;
        usleep(1);
    }
    timeout = DHT11_TIMEOUT_US;
    while (gpiod_line_get_value(line) == 0) {
        if (--timeout <= 0) return -1;
        usleep(1);
    }
    timeout = DHT11_TIMEOUT_US;
    while (gpiod_line_get_value(line) == 1) {
        if (--timeout <= 0) return -1;
        usleep(1);
    }

    /* Read 40 data bits */
    for (int i = 0; i < 40; i++) {
        /* Wait for low-to-high transition */
        timeout = DHT11_TIMEOUT_US;
        while (gpiod_line_get_value(line) == 0) {
            if (--timeout <= 0) return -1;
            usleep(1);
        }

        /* Measure high duration: ~26-28us = '0', ~70us = '1' */
        timeout = DHT11_TIMEOUT_US;
        counter = 0;
        while (gpiod_line_get_value(line) == 1) {
            if (++counter == 255) return -1;
            if (--timeout <= 0) return -1;
            usleep(1);
        }

        /* Determine bit value: ~26us = '0', ~70us = '1' */
        if (counter > 40) {
            data[j / 8] |= (1 << (7 - (j % 8)));
        }
        j++;
    }

    /* Verify checksum */
    uint8_t checksum = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
    if (checksum != data[4]) {
        fprintf(stderr, "Checksum error: computed 0x%02X, received 0x%02X\n", checksum, data[4]);
        return -2;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
