        fprintf(stderr, "Failed to get GPIO line %d: %s\n", DHT11_PIN, strerror(errno));
        goto cleanup;
    }

    printf("DHT11 sensor reading started on GPIO %d. Press Ctrl+C to exit.\n", DHT11_PIN);

    while (running) {
        uint8_t data[5] = {0};
        int result = read_dht11(line, data);

