#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 2
#define PWM_PIN_2 3
#define PWM_PIN_3 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define PWM_DUTY_CYCLE 500
#define PWM_PERIOD_US (1000000 / PWM_FREQ)

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_pwm_pin(int pin, int duty_cycle) {
    if (gpioPWM(pin, duty_cycle) < 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) < 0 ||
        gpioSetMode(PWM_PIN_2, PI_OUTPUT) < 0 ||
        gpioSetMode(PWM_PIN_3, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) < 0 ||
        gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) < 0 ||
        gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (set_pwm_pin(PWM_PIN_1, PWM_DUTY_CYCLE) < 0 ||
        set_pwm_pin(PWM_PIN_2, PWM_DUTY_CYCLE) < 0 ||
        set_pwm_pin(PWM_PIN_3, PWM_DUTY_CYCLE) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("PWM output on GPIO %d, GPIO %d, GPIO %d (range %d, freq %d Hz, duty %d%%)\n",
           PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_RANGE, PWM_FREQ, PWM_DUTY_CYCLE);

    while (running) {
        sleep(0.15);
    }

    cleanup();
    printf("PWM output stopped.\n");
    return EXIT_SUCCESS;
}

