        fprintf(stderr, "Failed to request line %d as input: %s\n", GPIO_LINE_OFFSET_1, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line2, "gpio-monitor") < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n", GPIO_LINE_OFFSET_2, strerror(errno));
        goto cleanup;
