#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define DS18B20_GPIO_1 4
#define DS18B20_GPIO_2 17
#define DS18B20_GPIO_3 18
#define SLEEP_INTERVAL_SEC 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_temperature(int gpio_pin) {
    char filename[64];
    char buffer[256];
    FILE *fp;
    int ret;

    snprintf(filename, sizeof(filename), "/sys/bus/w1/devices/28-%02X%02X%02X%02X%02X%02X%02X%02X/w1_slave",
             DS18B20_GPIO_1, DS18B20_GPIO_2, DS18B20_GPIO_3,
             gpio_pin & 0x7F, (gpio_pin >> 7) & 0x7F,
             (gpio_pin >> 14) & 0x7F, (gpio_pin >> 21) & 0x7F,
             (gpio_pin >> 28) & 0x7F);

    fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        return -1;
    }

    if (!fgets(buffer, sizeof(buffer), fp)) {
        fprintf(stderr, "Error reading from %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);

    if (strstr(buffer, "YES") == NULL) {
        fprintf(stderr, "DS18B20 not present on GPIO %d\n", gpio_pin);
        return -1;
    }

    char *temp_str = strstr(buffer, "t=");
    if (!temp_str) {
        fprintf(stderr, "Invalid temperature data from %s\n", filename);
        return -1;
    }

    char *endptr;
    long temp_raw = strtol(temp_str + 2, &endptr, 10);
    if (*endptr != '\0' || temp_raw < -55000 || temp_raw > 125000) {
        fprintf(stderr, "Invalid temperature value from %s\n", filename);
        return -1;
    }

    return (int)(temp_raw / 1000);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    while (program_running) {
        int temp1 = read_temperature(DS18B20_GPIO_1);
        int temp2 = read_temperature(DS18B20_GPIO_2);
        int temp3 = read_temperature(DS18B20_GPIO_3);

        if (temp1 == -1 || temp2 == -1 || temp3 == -1) {
            fprintf(stderr, "Error reading temperature from one or more GPIOs.\n");
            break;
        }

        printf("Temperature on GPIO %d: %d C\n", DS18B20_GPIO_1, temp1);
        printf("Temperature on GPIO %d: %d C\n", DS18B20_GPIO_2, temp2);
        printf("Temperature on GPIO %d: %d C\n", DS18B20_GPIO_3, temp3);
        printf("\n");

        sleep(SLEEP_INTERVAL_SEC);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define HTU21D_ADDR 0x40
#define I2C_DEV "/dev/i2c-1"
#define MEASUREMENT_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_htu21d(int fd, float *temperature, float *humidity) {
    uint8_t data[3];

    if (i2c_write_byte(fd, 0xE3) < 0) return -1;
    usleep(15000);

    if (i2c_read_bytes(fd, data, 3) < 0) return -1;

    uint16_t raw_humidity = (data[0] << 8) | data[1];
    uint16_t raw_temperature = (data[2] << 8) | data[1];

    float humidity_ratio = (float)raw_humidity / 65535.0f;
    float temperature_celsius = -46.85f + 175.72f * humidity_ratio;

    if (temperature_celsius < -40.0f || temperature_celsius > 125.0f) {
        fprintf(stderr, "Temperature out of range: %.2f C\n", temperature_celsius);
        return -1;
    }

    *temperature = temperature_celsius;
    *humidity = humidity_ratio;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", HTU21D_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    while (running) {
        float temperature, humidity;

        if (read_htu21d(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity * 100.0f);
        } else {
            fprintf(stderr, "Failed to read HTU21D data\n");
        }

        for (int i = 0; i < MEASUREMENT_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    close(fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

