#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PIN_1 17
#define DHT22_PIN_2 22
#define DHT22_PIN_3 23
#define DHT22_PIN_4 24

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht22(struct gpiod_line *line1, struct gpiod_line *line2, struct gpiod_line *line3, struct gpiod_line *line4, int *humidity, int *temperature) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = 1;
    int counter = 0;
    int j = 0;

    // Send start signal
    if (gpiod_line_request_output(line1, "dht22", 0) < 0 ||
        gpiod_line_request_output(line2, "dht22", 0) < 0 ||
        gpiod_line_request_output(line3, "dht22", 0) < 0 ||
        gpiod_line_request_output(line4, "dht22", 0) < 0) {
        fprintf(stderr, "Failed to request output lines\n");
        return -1;
    }

    // Pull low for 1ms
    gpiod_line_set_value(line1, 0);
    gpiod_line_set_value(line2, 0);
    gpiod_line_set_value(line3, 0);
    gpiod_line_set_value(line4, 0);
    usleep(1000);

    // Pull high for 30us
    gpiod_line_set_value(line1, 1);
    gpiod_line_set_value(line2, 1);
    gpiod_line_set_value(line3, 1);
    gpiod_line_set_value(line4, 1);
    usleep(30);

    // Switch to input
    if (gpiod_line_request_input(line1, "dht22") < 0 ||
        gpiod_line_request_input(line2, "dht22") < 0 ||
        gpiod_line_request_input(line3, "dht22") < 0 ||
        gpiod_line_request_input(line4, "dht22") < 0) {
        fprintf(stderr, "Failed to request input lines\n");
        return -1;
    }

    // Wait for sensor response
    counter = 0;
    while (gpiod_line_get_value(line1) == laststate) {
        counter++;
        usleep(1);
        if (counter > 100) {
            fprintf(stderr, "DHT22 response timeout\n");
            return -1;
        }
    }
    laststate = gpiod_line_get_value(line1);

    // Read 40 bits
    for (int i = 0; i < 40; i++) {
        counter = 0;
        while (gpiod_line_get_value(line1) == laststate) {
            counter++;
            usleep(1);
            if (counter > 100) {
                fprintf(stderr, "DHT22 timeout\n");
                return -1;
            }
        }
        laststate = gpiod_line_get_value(line1);

        if (counter > 40) {
            data[j / 8] |= (1 << (7 - (j % 8)));
        }
        j++;
    }

    // Checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "DHT22 checksum error\n");
        return -1;
    }

    *humidity = (data[0] << 8) + data[1];
    *temperature = (data[2] << 8) + data[3];

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL, *line3 = NULL, *line4 = NULL;
    int humidity, temperature;

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    // Get GPIO lines
    line1 = gpiod_chip_get_line(chip, DHT22_PIN_1);
    line2 = gpiod_chip_get_line(chip, DHT22_PIN_2);
    line3 = gpiod_chip_get_line(chip, DHT22_PIN_3);
    line4 = gpiod_chip_get_line(chip, DHT22_PIN_4);

    if (!line1 || !line2 || !line3 || !line4) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        goto cleanup;
    }

    // Main loop
    while (running) {
        if (read_dht22(line1, line2, line3, line4, &humidity, &temperature) == 0) {
            printf("Humidity: %d%%, Temperature: %d°C\n", humidity, temperature);
        } else {
            fprintf(stderr, "Failed to read DHT22 data\n");
        }
        sleep(2);
    }

cleanup:
    // Release lines
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (line4) gpiod_line_release(line4);
    if (chip) gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27
#define PWM_RANGE 255
#define PWM_FREQ 1000
#define PWM_DUTY_CYCLE 128

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_pwm_range(int pin, int range) {
    if (gpioSetPWMrange(pin, range) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d, %d) failed\n", pin, range);
        return -1;
    }
    return 0;
}

static int set_pwm_frequency(int pin, int freq) {
    if (gpioSetPWMfrequency(pin, freq) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d, %d) failed\n", pin, freq);
        return -1;
    }
    return 0;
}

static int set_pwm_duty_cycle(int pin, int duty) {
    if (gpioPWM(pin, duty) < 0) {
        fprintf(stderr, "Error: gpioPWM(%d, %d) failed\n", pin, duty);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (set_pwm_range(PWM_PIN_1, PWM_RANGE) != 0 ||
        set_pwm_range(PWM_PIN_2, PWM_RANGE) != 0 ||
        set_pwm_range(PWM_PIN_3, PWM_RANGE) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (set_pwm_frequency(PWM_PIN_1, PWM_FREQ) != 0 ||
        set_pwm_frequency(PWM_PIN_2, PWM_FREQ) != 0 ||
        set_pwm_frequency(PWM_PIN_3, PWM_FREQ) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        if (set_pwm_duty_cycle(PWM_PIN_1, PWM_DUTY_CYCLE) != 0 ||
            set_pwm_duty_cycle(PWM_PIN_2, PWM_DUTY_CYCLE) != 0 ||
            set_pwm_duty_cycle(PWM_PIN_3, PWM_DUTY_CYCLE) != 0) {
            break;
        }
        sleep(0.5);
    }

    cleanup();
    return EXIT_SUCCESS;
}

