#define PWM_PIN 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define PWM_DUTY_CYCLE 128
#define POLL_INTERVAL_US 200000  /* 200 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure PWM pin */
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start PWM at 128 duty cycle */
    if (gpioPWM(PWM_PIN, PWM_DUTY_CYCLE) != 0) {
        fprintf(stderr, "Error: failed to start PWM on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM on GPIO %d started. Press Ctrl+C to stop.\n", PWM_PIN);

    /* Main loop: report state and wait for signal */
    while (running) {
        int duty = gpioGetPWMdutycycle(PWM_PIN);
        if (duty < 0) {
            fprintf(stderr, "Warning: failed to read PWM duty cycle on GPIO %d.\n", PWM_PIN);
        } else {
            printf("PWM duty cycle: %d\n", duty);
        }
        usleep(POLL_INTERVAL_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpioPWM(PWM_PIN, 0);  /* Stop PWM */
    gpioTerminate();
    printf("PWM stopped and pigpio terminated.\n");
    return EXIT_SUCCESS;
}

