        fd_set fds;
        struct timeval tv;

        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 2;
        tv.tv_usec = 0;

        ret = select(fd + 1, &fds, NULL, NULL, &tv);
        if (ret == -1) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error in select: %s\n", strerror(errno));
            break;
        } else if (ret == 0) {
            fprintf(stderr, "select timeout\n");
            break;
        }

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        ret = xioctl(fd, VIDIOC_DQBUF, &buf);
        if (ret == -1) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
            break;
        }

        fp = fopen(IMAGE_FILE, "wb");
        if (fp == NULL) {
            fprintf(stderr, "Error opening %s: %s\n", IMAGE_FILE, strerror(errno));
            goto cleanup;
        }

        size_t written = fwrite(buffer, 1, buf.bytesused, fp);
        if (written != buf.bytesused) {
            fprintf(stderr, "Error writing to %s: %s\n", IMAGE_FILE, strerror(errno));
            fclose(fp);
            fp = NULL;
            goto cleanup;
        }

        if (fclose(fp) == EOF) {
            fprintf(stderr, "Error closing %s: %s\n", IMAGE_FILE, strerror(errno));
            fp = NULL;
            goto cleanup;
        }

        fp = NULL;

        printf("Image saved to %s\n", IMAGE_FILE);

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = 0;

        ret = xioctl(fd, VIDIOC_QBUF, &buf);
        if (ret == -1) {
            fprintf(stderr, "Error re-queuing buffer: %s\n", strerror(errno));
            break;
        }

        break;
    }

    enum v4l2_buf_type stop_type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    xioctl(fd, VIDIOC_STREAMOFF, &stop_type);

cleanup:
    if (buffer != NULL) {
        munmap(buffer, buf.length);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    if (fd != -1) {
        close(fd);
    }
    return EXIT_SUCCESS;
}

