static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig)
{
    (void)sig;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the lines */
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line(GPIO_PIN_1)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line(GPIO_PIN_2)");
        goto cleanup;
    }

    /* Request both lines as inputs */
    ret = gpiod_line_request_input(line1, "gpio-control");
    if (ret < 0) {
        perror("gpiod_line_request_input(line1)");
        goto cleanup;
    }

    ret = gpiod_line_request_input(line2, "gpio-control");
    if (ret < 0) {
        perror("gpiod_line_request_input(line2)");
        goto cleanup;
    }

    printf("Monitoring GPIO %d and %d. Press Ctrl+C to exit.\n",
           GPIO_PIN_1, GPIO_PIN_2);

    while (keep_running) {
        int val1 = gpiod_line_get_value(line1);
        int val2 = gpiod_line_get_value(line2);

        if (val1 < 0) {
            perror("gpiod_line_get_value(line1)");
            break;
        }
        if (val2 < 0) {
            perror("gpiod_line_get_value(line2)");
            break;
        }

        printf("GPIO %d: %d, GPIO %d: %d\n",
               GPIO_PIN_1, val1, GPIO_PIN_2, val2);
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    printf("\nExiting cleanly.\n");

cleanup:
    if (line1)
        gpiod_line_release(line1);
    if (line2)
        gpiod_line_release(line2);
    if (chip)
        gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

