static int ssd1306_command(uint8_t cmd) {
    uint8_t buf[2] = {0x00, cmd};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("ssd1306_command: write failed");
        return -1;
    }
    return 0;
}

static int ssd1306_data(const uint8_t *data, size_t len) {
    uint8_t buf[len + 1];
    buf[0] = 0x40;
    memcpy(buf + 1, data, len);
    if (write(i2c_fd, buf, len + 1) != (ssize_t)(len + 1)) {
        perror("ssd1306_data: write failed");
        return -1;
    }
    return 0;
}

static int ssd1306_init(void) {
