}

static int ssd1306_draw_pixel(int x, int y, int color) {
    if (x < 0 || x >= SSD1306_WIDTH || y < 0 || y >= SSD1306_HEIGHT) return -1;
    int page = y / 8;
    int bit = y % 8;
    uint8_t offset = 1 << bit;
    uint8_t *data = (uint8_t *)malloc(1 + (SSD1306_WIDTH / 8));
    if (!data) {
        perror("ssd1306_draw_pixel: malloc failed");
        return -1;
    }
    data[0] = 0x40;
    if (color) {
        data[1 + (x / 8)] |= offset;
    } else {
        data[1 + (x / 8)] &= ~offset;
    }
    if (ssd1306_data(data, sizeof(data)) < 0) {
        free(data);
        return -1;
    }
    free(data);
    return 0;
}

static int ssd1306_draw_line(int x1, int y1, int x2, int y2, int color) {
    int dx = abs(x2 - x1);
    int dy = abs(y2 - y1);
    int sx = (x1 < x2) ? 1 : -1;
    int sy = (y1 < y2) ? 1 : -1;
    int err = dx - dy;
    int e2;
    while (1) {
        if (ssd1306_draw_pixel(x1, y1, color) < 0) return -1;
        if (x1 == x2 && y1 == y2) break;
        e2 = 2 * err;
        if (e2 > -dy) {
            err -= dy;
            x1 += sx;
        }
        if (e2 < dx) {
            err += dx;
            y1 += sy;
        }
    }
    return 0;
}

static int ssd1306_draw_rect(int x, int y, int w, int h, int color) {
    for (int i = 0; i < w; i++) {
        if (ssd1306_draw_line(x + i, y, x + i, y + h - 1, color) < 0) return -1;
    }
    for (int i = 0; i < h; i++) {
        if (ssd1306_draw_line(x, y + i, x + w - 1, y + i, color) < 0) return -1;
    }
    return 0;
}

static int ssd1306_draw_circle(int x, int y, int r, int color) {
    for (int i = 0; i < r; i++) {
        if (ssd1306_draw_line(x - r + i, y, x + r - i, y, color) < 0) return -1;
        if (ssd1306_draw_line(x, y - r + i, x, y + r - i, color) < 0) return -1;
    }
    return 0;
}

static int ssd1306_draw_string(int x, int y, const char *str, int color) {
