}

static double measure_distance(struct gpiod_line *echo) {
    if (trigger_sensor(echo) < 0) {
        return -1.0;
    }
    if (read_echo_pin(echo) < 0) {
        return -1.0;
    }
    int start_tick = 0, end_tick = 0;
    int val;
    for (int i = 0; i < TIMEOUT_US; i++) {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("Failed to read echo pin");
            return -1.0;
        }
        if (val == 1) {
            start_tick = i;
            break;
        }
        usleep(1);
    }
    for (int i = 0; i < TIMEOUT_US; i++) {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("Failed to read echo pin");
            return -1.0;
        }
        if (val == 0) {
            end_tick = i;
            break;
        }
        usleep(1);
    }
    if (start_tick == 0 || end_tick == 0) {
        fprintf(stderr, "Echo pin did not change state\n");
        return -1.0;
    }
    double pulse_duration = (end_tick - start_tick) * 1.0;
    return pulse_duration * SPEED_OF_SOUND / 2000000.0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL, *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
