#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <string.h>

#define HD44780_I2C_ADDR 0x3E
#define HD44780_WIDTH 16
#define HD44780_HEIGHT 2

static int i2c_fd = -1;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int hd44780_write_byte(int fd, unsigned char data, unsigned char mode) {
    unsigned char buf[2];
    buf[0] = (data & 0xF0) | mode;
    buf[1] = ((data << 4) & 0xF0) | mode;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    usleep(1000);
    return 0;
}

int hd44780_send_command(int fd, unsigned char cmd) {
    return hd44780_write_byte(fd, cmd, 0);
}

int hd44780_send_data(int fd, unsigned char data) {
    return hd44780_write_byte(fd, data, 1);
}

int hd44780_init(int fd) {
    usleep(50000);
    hd44780_write_byte(fd, 0x30, 0);
    usleep(5000);
    hd44780_write_byte(fd, 0x30, 0);
    usleep(150);
    hd44780_write_byte(fd, 0x30, 0);
    usleep(150);
    hd44780_write_byte(fd, 0x20, 0);
    usleep(150);
    hd44780_send_command(fd, 0x28);
    hd44780_send_command(fd, 0x0C);
    hd44780_send_command(fd, 0x06);
    hd44780_send_command(fd, 0x01);
    return 0;
}

int hd44780_clear(int fd) {
    hd44780_send_command(fd, 0x01);
    usleep(2000);
    return 0;
}

int hd44780_set_cursor(int fd, int row, int col) {
    int addr;
    if (row == 0) {
        addr = 0x00 + col;
    } else {
        addr = 0x40 + col;
    }
    hd44780_send_command(fd, 0x80 | addr);
    return 0;
}

int hd44780_display_string(int fd, const char *str) {
    while (*str) {
        hd44780_send_data(fd, (unsigned char)*str++);
    }
    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open /dev/i2c-1");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HD44780_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    if (hd44780_init(i2c_fd) < 0) {
        fprintf(stderr, "HD44780 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    while (keep_running) {
        hd44780_clear(i2c_fd);
        hd44780_set_cursor(i2c_fd, 0, 0);
        hd44780_display_string(i2c_fd, "Temperature:");
        hd44780_set_cursor(i2c_fd, 1, 0);
        hd44780_display_string(i2c_fd, "Humidity:");
        sleep(10);
    }

    hd44780_clear(i2c_fd);
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

