        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_14, strerror(errno));
        goto cleanup;
    }

    line15 = gpiod_chip_get_line(chip, GPIO_LINE_15);
    if (line15 == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_15, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as inputs */
    if (gpiod_line_request_input(line14, "gpio-monitor") < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n", GPIO_LINE_14, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line15, "gpio-monitor") < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n", GPIO_LINE_15, strerror(errno));
        goto cleanup;
    }

    printf("Monitoring GPIO %d and %d every %d seconds. Press Ctrl+C to exit.\n",
           GPIO_LINE_14, GPIO_LINE_15, POLL_INTERVAL_SEC);
    fflush(stdout);

    while (keep_running) {
        int val14 = gpiod_line_get_value(line14);
        int val15 = gpiod_line_get_value(line15);

        if (val14 < 0) {
            fprintf(stderr, "Error reading GPIO %d: %s\n", GPIO_LINE_14, strerror(errno));
        } else {
            printf("GPIO %d: %d\n", GPIO_LINE_14, val14);
        }

        if (val15 < 0) {
            fprintf(stderr, "Error reading GPIO %d: %s\n", GPIO_LINE_15, strerror(errno));
        } else {
            printf("GPIO %d: %d\n", GPIO_LINE_15, val15);
        }

        fflush(stdout);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line14 != NULL) {
        gpiod_line_release(line14);
    }
    if (line15 != NULL) {
        gpiod_line_release(line15);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor_data"
#define MQTT_CLIENT_ID "sensor_client"
#define READ_INTERVAL_US 100000  /* 100 ms */
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static struct mosquitto *mosq = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_mqtt(void) {
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: mosquitto_new failed\n");
        return -1;
    }
    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: mosquitto_connect failed (rc=%d)\n", rc);
        mosquitto_destroy(mosq);
        mosq = NULL;
        mosquitto_lib_cleanup();
        return -1;
    }
    return 0;
}

static int publish_sensor_data(const char *data) {
    int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(data), data, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: mosquitto_publish failed (rc=%d)\n", rc);
        return -1;
    }
    return 0;
}

static void cleanup_mqtt(void) {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    mosquitto_lib_cleanup();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (initialize_mqtt() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Publishing sensor data to %s every %d ms. Press Ctrl+C to stop.\n",
           MQTT_TOPIC, READ_INTERVAL_US / 1000);

    while (running) {
        char data[16];
        time_t rawtime;
        struct tm *timeinfo;

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        if (!timeinfo) {
            fprintf(stderr, "Error: localtime failed\n");
            break;
        }

        if (strftime(data, sizeof(data), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
            fprintf(stderr, "Error: strftime failed\n");
            break;
        }

        if (publish_sensor_data(data) != 0) {
            fprintf(stderr, "Error: failed to publish sensor data\n");
            break;
        }

        printf("Published: %s\n", data);

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 10 && running; i++) {
            gpioDelay(READ_INTERVAL_US / 10);
        }
    }

    cleanup_mqtt();
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 23
#define CONSUMER "digital-output"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Digital output control started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_LINE);

    /* Main loop: toggle every 5 seconds */
    while (keep_running) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(1)");
            break;
        }
        printf("GPIO %d set HIGH\n", GPIO_LINE);
        sleep(5);

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(0)");
            break;
        }
        printf("GPIO %d set LOW\n", GPIO_LINE);
        sleep(5);
    }

    /* Clean up: release line and close chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 22
#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define TIMEOUT_US 100000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int trigger_sensor(struct gpiod_line *trigger) {
    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Error: Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    usleep(2);
    if (gpiod_line_set_value(trigger, 1) < 0) {
        fprintf(stderr, "Error: Failed to set trigger high: %s\n", strerror(errno));
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Error: Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_echo_pulse(struct gpiod_line *echo) {
    int start_tick = 0, end_tick = 0;
    int timeout = 0;

    /* Wait for echo to go high (start of pulse) */
    while (gpiod_line_get_value(echo) == 0) {
        if (++timeout > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo start timeout (sensor absent or not responding)\n");
            return -1;
        }
        usleep(1);
    }
    start_tick = timeout;

    /* Wait for echo to go low (end of pulse) */
    timeout = 0;
    while (gpiod_line_get_value(echo) == 1) {
        if (++timeout > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo end timeout (sensor not responding)\n");
            return -1;
        }
        usleep(1);
    }
    end_tick = timeout;

    return end_tick - start_tick;
}

static double calculate_distance(int pulse_width_us) {
    return (double)pulse_width_us * SPEED_OF_SOUND / 2000000.0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL, *echo = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get trigger line */
    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        fprintf(stderr, "Error: Failed to get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    /* Get echo line */
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Error: Failed to get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request trigger line as output, initial value low */
    if (gpiod_line_request_output(trigger, "hcsr04-trigger", 0) < 0) {
        fprintf(stderr, "Error: Failed to request trigger line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request echo line as input */
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Error: Failed to request echo line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        if (trigger_sensor(trigger) < 0) {
            fprintf(stderr, "Warning: Trigger failed, retrying...\n");
            sleep(1);
            continue;
        }

        int pulse_width = read_echo_pulse(echo);
        if (pulse_width < 0) {
            fprintf(stderr, "Warning: Echo read failed, retrying...\n");
            sleep(1);
            continue;
        }

        double distance = calculate_distance(pulse_width);

        if (distance >= MIN_DISTANCE_CM && distance <= MAX_DISTANCE_CM) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Warning: Distance out of range: %.2f cm\n", distance);
        }

        sleep(1);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure trigger is low before releasing */
    if (trigger) {
        gpiod_line_set_value(trigger, 0);
        gpiod_line_release(trigger);
    }
    if (echo) {
        gpiod_line_release(echo);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

