#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor_data"
#define MQTT_CLIENT_ID "sensor_client"
#define MQTT_KEEPALIVE 60

static volatile sig_atomic_t running = 1;
static struct mosquitto *mosq = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void on_connect(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker.\n");
    } else {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", mosquitto_strerror(result));
    }
}

static void on_disconnect(struct mosquitto *m, void *userdata, int rc) {
    (void)m;
    (void)userdata;
    if (rc == 0) {
        printf("Disconnected from MQTT broker.\n");
    } else {
        fprintf(stderr, "Disconnected from MQTT broker with error: %s\n", mosquitto_strerror(rc));
    }
}

static void on_message(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m;
    (void)userdata;
    if (message->payloadlen > 0) {
        printf("Received message on topic %s: %s\n", message->topic, (char *)message->payload);
    } else {
        printf("Received message on topic %s (no payload)\n", message->topic);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Failed to create mosquitto instance\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Failed to start mosquitto loop: %s\n", mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Publishing sensor data to %s every 5 seconds. Press Ctrl+C to exit.\n", MQTT_TOPIC);

    while (running) {
        sleep(5);
    }

    printf("\nShutting down...\n");
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 255
#define PWM_FREQ 1000
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Warning: failed to install SIGINT handler");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Warning: failed to install SIGTERM handler");
    }

    printf("PWM on GPIO %d started. Press Ctrl+C to exit.\n", PWM_PIN);

    while (running) {
        for (int i = 0; i <= PWM_RANGE && running; i++) {
            if (gpioPWM(PWM_PIN, i) != 0) {
                fprintf(stderr, "Error: failed to set PWM on GPIO %d.\n", PWM_PIN);
                running = 0;
                break;
            }
            printf("PWM on GPIO %d: %d/%d\n", PWM_PIN, i, PWM_RANGE);
            sleep(1);
        }
    }

    printf("\nCleaning up...\n");
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("PWM stopped on GPIO %d.\n", PWM_PIN);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SPEED_OF_SOUND 34300.0
#define TIMEOUT_US 30000

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

static int trigger_sensor(struct gpiod_line *trigger) {
    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Error: Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    usleep(2);
    if (gpiod_line_set_value(trigger, 1) < 0) {
        fprintf(stderr, "Error: Failed to set trigger high: %s\n", strerror(errno));
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Error: Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_echo_pulse(struct gpiod_line *echo) {
    int start_tick = 0, end_tick = 0;
    int timeout = 0;

    while (gpiod_line_get_value(echo) == 0) {
        if (timeout++ > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo start timeout (sensor absent or not responding)\n");
            return -1;
        }
        usleep(1);
    }
    start_tick = timeout;

    timeout = 0;
    while (gpiod_line_get_value(echo) == 1) {
        if (timeout++ > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo end timeout (sensor absent or not responding)\n");
            return -1;
        }
        usleep(1);
    }
    end_tick = timeout;

    return end_tick - start_tick;
}

static double calculate_distance(int pulse_width_us) {
    return (double)pulse_width_us * SPEED_OF_SOUND / 2000000.0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL, *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        fprintf(stderr, "Error: Failed to get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Error: Failed to get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, "hc-sr04-trigger", 0) < 0) {
        fprintf(stderr, "Error: Failed to request trigger line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Error: Failed to request echo line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        if (trigger_sensor(trigger) < 0) {
            fprintf(stderr, "Error: Trigger sensor failed, retrying...\n");
            sleep(1);
            continue;
        }

        int pulse_width = read_echo_pulse(echo);
        if (pulse_width < 0) {
            fprintf(stderr, "Error: Echo read failed, retrying...\n");
            sleep(1);
            continue;
        }

        double distance = calculate_distance(pulse_width);

        if (distance < 2.0 || distance > 400.0) {
            fprintf(stderr, "Warning: Distance out of range: %.2f cm\n", distance);
        } else {
            printf("Distance: %.2f cm\n", distance);
        }

        sleep(0.2);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 23

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    int pwm_pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    int pwm_values[] = {0, 0, 0, 0};

    while (program_running) {
        for (int i = 0; i < 4; i++) {
            if (gpioPWM(pwm_pins[i], pwm_values[i]) != 0) {
                fprintf(stderr, "Failed to set PWM on pin %d\n", pwm_pins[i]);
                program_running = 0;
                break;
            }
        }
        if (!program_running) break;
        sleep(0.1);
    }

    for (int i = 0; i < 4; i++) {
        gpioPWM(pwm_pins[i], 0);
    }

    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor_data"
#define MQTT_CLIENT_ID "sensor_client"
#define MAX_READ_LENGTH 256
#define READ_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;
static struct mosquitto *mosq = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(char *buffer, size_t buffer_size) {
    FILE *fp = fopen("/dev/random", "r");
    if (!fp) {
        fprintf(stderr, "Error opening /dev/random: %s\n", strerror(errno));
        return -1;
    }
    size_t bytes_read = fread(buffer, 1, buffer_size - 1, fp);
    fclose(fp);
    if (bytes_read == 0) {
        fprintf(stderr, "Error reading from /dev/random\n");
        return -1;
    }
    buffer[bytes_read] = '\0';
    return 0;
}

static int publish_sensor_data(const char *data) {
    int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(data), data, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing to MQTT: %s\n", mosquitto_strerror(rc));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error creating mosquitto instance\n");
        gpioTerminate();
        return 1;
    }

    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error starting mosquitto loop: %s\n", mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    char sensor_data[MAX_READ_LENGTH];
    while (running) {
        if (read_sensor_data(sensor_data, sizeof(sensor_data)) == 0) {
            if (publish_sensor_data(sensor_data) != 0) {
                fprintf(stderr, "Error publishing sensor data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        sleep(READ_INTERVAL_SEC);
    }

    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>
#include <mosquitto.h>

#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_BEGIN 0x8000
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor_data"
#define READINGS_COUNT 10
#define SAMPLE_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int16_t raw_data[READINGS_COUNT];
static int pigpio_initialized = 0;
static struct mosquitto *mosq = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_pigpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    pigpio_initialized = 1;
    return 0;
}

static int init_ads1115(void) {
    int handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        return -1;
    }

    uint16_t config = ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0_GND | ADS1115_CONFIG_PGA_4_096V |
                      ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;

    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "Error: Failed to write ADS1115 config: %s\n", strerror(errno));
        i2cClose(handle);
        return -1;
    }

    gpioDelay(10000);
    return handle;
}

static int read_ads1115(int handle, int16_t *value) {
    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: Failed to set conversion register: %s\n", strerror(errno));
        return -1;
    }

    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read conversion data: %s\n", strerror(errno));
        return -1;
    }

    *value = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int publish_data(struct mosquitto *mosq, const char *topic, int16_t value) {
    char payload[16];
    int len = snprintf(payload, sizeof(payload), "%d", value);
    if (len < 0 || (size_t)len >= sizeof(payload)) {
        fprintf(stderr, "Error: Payload formatting failed\n");
        return -1;
    }

    int rc = mosquitto_publish(mosq, NULL, topic, len, payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Failed to publish data to MQTT: %s\n", mosquitto_strerror(rc));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (mosq != NULL) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    if (pigpio_initialized) {
        gpioTerminate();
        pigpio_initialized = 0;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_pigpio() != 0) {
        return 1;
    }

    int handle = init_ads1115();
    if (handle < 0) {
        cleanup();
        return 1;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (mosq == NULL) {
        fprintf(stderr, "Error: Failed to create MQTT client\n");
        cleanup();
        return 1;
    }

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Failed to connect to MQTT broker: %s\n", mosquitto_strerror(rc));
        cleanup();
        return 1;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Failed to start MQTT loop: %s\n", mosquitto_strerror(rc));
        cleanup();
        return 1;
    }

    printf("Starting ADS1115 sensor readings...\n");

    for (int i = 0; i < READINGS_COUNT && running; i++) {
        int16_t value;
        if (read_ads1115(handle, &value) != 0) {
            fprintf(stderr, "Error: Failed to read ADS1115 value at index %d\n", i);
            break;
        }

        if (value < -32767 || value > 32767) {
            fprintf(stderr, "Warning: ADS1115 value out of range at index %d: %d\n", i, value);
        }

        raw_data[i] = value;
        printf("Reading %d: %d\n", i + 1, value);

        if (publish_data(mosq, MQTT_TOPIC, value) != 0) {
            break;
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nExiting...\n");
    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_17 17
#define GPIO_LINE_18 18
#define POLL_INTERVAL_SEC 0.05

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line18 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO lines */
    line17 = gpiod_chip_get_line(chip, GPIO_LINE_17);
    if (!line17) {
        perror("gpiod_chip_get_line(17)");
        goto cleanup;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_LINE_18);
    if (!line18) {
        perror("gpiod_chip_get_line(18)");
        goto cleanup;
    }

    /* Request both lines as inputs */
    if (gpiod_line_request_input(line17, "gpio-monitor") < 0) {
        perror("gpiod_line_request_input(17)");
        goto cleanup;
    }

    if (gpiod_line_request_input(line18, "gpio-monitor") < 0) {
        perror("gpiod_line_request_input(18)");
        goto cleanup;
    }

    printf("Monitoring GPIO %d and GPIO %d every %d seconds. Press Ctrl+C to exit.\n",
           GPIO_LINE_17, GPIO_LINE_18, (int)(POLL_INTERVAL_SEC * 1000));

    /* Main polling loop */
    while (keep_running) {
        int val17 = gpiod_line_get_value(line17);
        int val18 = gpiod_line_get_value(line18);

        if (val17 < 0) {
            perror("gpiod_line_get_value(17)");
            goto cleanup;
        }
        if (val18 < 0) {
            perror("gpiod_line_get_value(18)");
            goto cleanup;
        }

        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_LINE_17, val17, GPIO_LINE_18, val18);
        fflush(stdout);

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 10 && keep_running; i++) {
            usleep(POLL_INTERVAL_SEC * 1000000 / 10);
        }
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define CONSUMER "gpio-output"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d initialized as output. Press Ctrl+C to exit.\n", GPIO_LINE);

    /* Main loop: report state every 5 seconds */
    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }
        printf("GPIO %d: %d\n", GPIO_LINE, val);
        fflush(stdout);
        sleep(5);
    }

    /* Clean up: release line and close chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
