#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor_data"
#define MQTT_CLIENT_ID "sensor_client"
#define MQTT_KEEPALIVE 60

static volatile sig_atomic_t running = 1;
static struct mosquitto *mosq = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void mqtt_connect_callback(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker.\n");
    } else {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", mosquitto_strerror(result));
    }
}

static void mqtt_disconnect_callback(struct mosquitto *m, void *userdata, int result) {
    (void)m;
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Disconnected from MQTT broker.\n");
    } else {
        fprintf(stderr, "Failed to disconnect from MQTT broker: %s\n", mosquitto_strerror(result));
    }
}

static void mqtt_message_callback(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m;
    (void)userdata;
    if (message->payloadlen > 0) {
        char *payload = malloc(message->payloadlen + 1);
        if (payload) {
            memcpy(payload, message->payload, message->payloadlen);
            payload[message->payloadlen] = '\0';
            printf("Received message: %s\n", payload);
            free(payload);
        } else {
            fprintf(stderr, "Failed to allocate memory for message payload.\n");
        }
    } else {
        printf("Received empty message.\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Failed to create mosquitto instance\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(mosq, mqtt_disconnect_callback);
    mosquitto_message_callback_set(mosq, mqtt_message_callback);

    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Failed to start mosquitto loop: %s\n", mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Publishing sensor readings to %s every 5 seconds. Press Ctrl+C to exit.\n", MQTT_TOPIC);

    while (running) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        if (timeinfo) {
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            char message[128];
            snprintf(message, sizeof(message), "Sensor reading at %s", timestamp);

            int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(message), message, 0, false);
            if (rc != MOSQ_ERR_SUCCESS) {
                fprintf(stderr, "Failed to publish message: %s\n", mosquitto_strerror(rc));
            }
        } else {
            fprintf(stderr, "Failed to get local time.\n");
        }

        sleep(5);
    }

    printf("\nExiting gracefully...\n");
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
