#include <pigpio.h>

#define PWM_PIN_1 2
#define PWM_PIN_2 3
#define PWM_PIN_3 18
#define PWM_PIN_4 23
#define PWM_PIN_5 24

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler.\n");
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4, PWM_PIN_5};
    int num_pins = sizeof(pins) / sizeof(pins[0]);

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], 1000) != 0) {
            fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to initialise PWM on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("PWM output pins initialized (BCM): %d, %d, %d, %d, %d\n",
           PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4, PWM_PIN_5);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < num_pins; i++) {
            int val = gpioRead(pins[i]);
            if (val < 0) {
                fprintf(stderr, "Error: gpioRead failed on GPIO %d.\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("GPIO %d: %d\n", pins[i], val);
        }
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    for (int i = 0; i < num_pins; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
