#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>

#define UART_PORT "/dev/ttyS0"
#define BAUD_RATE B115200
#define MAX_BUFFER_SIZE 256

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_uart(const char *port, speed_t baud) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_lflag = 0;
    tty.c_oflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error setting SIGINT handler");
        return EXIT_FAILURE;
    }

    int fd = setup_uart(UART_PORT, BAUD_RATE);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    char buffer[MAX_BUFFER_SIZE];
    ssize_t bytes_read;

    while (running) {
        bytes_read = read(fd, buffer, sizeof(buffer) - 1);
        if (bytes_read < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("Error reading from UART");
            break;
        } else if (bytes_read == 0) {
            continue;
        }

        buffer[bytes_read] = '\0';
        printf("%s", buffer);
        fflush(stdout);
    }

    close(fd);
    return EXIT_SUCCESS;
}

