    timeout_count = 0;
    while (gpiod_line_get_value(line) == 1) {
        if (++timeout_count > DHT22_TIMEOUT_US) {
            fprintf(stderr, "DHT22 response timeout (sensor absent or wiring fault)\n");
            return -1;
        }
        usleep(1);
    }
    timeout_count = 0;
    while (gpiod_line_get_value(line) == 0) {
        if (++timeout_count > DHT22_TIMEOUT_US) {
            fprintf(stderr, "DHT22 response timeout (sensor absent or wiring fault)\n");
            return -1;
        }
        usleep(1);
    }
    timeout_count = 0;
    while (gpiod_line_get_value(line) == 1) {
        if (++timeout_count > DHT22_TIMEOUT_US) {
            fprintf(stderr, "DHT22 response timeout (sensor absent or wiring fault)\n");
            return -1;
        }
        usleep(1);
    }

    /* Read 40 bits */
    for (int i = 0; i < 40; i++) {
        /* Wait for low-to-high transition */
        timeout_count = 0;
        while (gpiod_line_get_value(line) == 0) {
            if (++timeout_count > DHT22_TIMEOUT_US) {
                fprintf(stderr, "DHT22 data timeout (bit %d)\n", i);
                return -1;
            }
            usleep(1);
        }

        /* Measure high duration: ~26-28us = '0', ~70us = '1' */
        timeout_count = 0;
        int high_start = 0;
        while (gpiod_line_get_value(line) == 1) {
            if (++timeout_count > DHT22_TIMEOUT_US) {
                fprintf(stderr, "DHT22 data timeout (bit %d)\n", i);
                return -1;
            }
            usleep(1);
        }
        int high_duration = timeout_count;

        /* Determine bit value: ~26us = '0', ~70us = '1' */
        if (high_duration > 40) {
            data[byte_idx] |= (1 << (7 - bit_idx));
        }

        bit_idx++;
        if (bit_idx == 8) {
            bit_idx = 0;
            byte_idx++;
        }
    }

    /* Verify checksum */
    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (checksum != data[4]) {
        fprintf(stderr, "DHT22 checksum error: computed 0x%02X, received 0x%02X\n", checksum, data[4]);
        return -2;
    }

    /* Convert raw data */
    uint16_t raw_humidity = (data[0] << 8) | data[1];
    uint16_t raw_temperature = (data[2] << 8) | data[3];

    *humidity = (float)raw_humidity / 10.0f;
    *temperature = (float)raw_temperature / 10.0f;

    if (raw_temperature & 0x8000) {
        *temperature = -*temperature;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float temperature, humidity;
    int ret;

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open GPIO chip 0 (Raspberry Pi GPIO controller) */
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip 0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get GPIO line 4 */
    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", DHT22_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("DHT22 sensor reader started on GPIO %d. Press Ctrl+C to exit.\n", DHT22_PIN);

    while (running) {
        ret = read_dht22(line, &temperature, &humidity);
        if (ret == 0) {
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);
        } else if (ret == -1) {
            fprintf(stderr, "DHT22 read failed (timeout or sensor absent)\n");
        } else {
            fprintf(stderr, "DHT22 read failed (checksum error)\n");
        }

        /* Sleep for 1 second, but wake early on signal */
        for (int i = 0; i < 10 && running; i++) {
            usleep(100000); /* 100ms */
        }
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PINS 4
#define POLL_INTERVAL_SEC 10

static const unsigned int pins[GPIO_PINS] = {17, 23, 24, 25};
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[GPIO_PINS];
static volatile sig_atomic_t keep_running = 1;

static void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

static void release_resources(void) {
    for (int i = 0; i < GPIO_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < GPIO_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n", pins[i], strerror(errno));
            release_resources();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(lines[i], "gpio-control", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output: %s\n", pins[i], strerror(errno));
            release_resources();
            return EXIT_FAILURE;
        }
    }

    printf("GPIO control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        for (int i = 0; i < GPIO_PINS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Failed to read GPIO line %u: %s\n", pins[i], strerror(errno));
                release_resources();
                return EXIT_FAILURE;
            }
            printf("GPIO %u: %d\n", pins[i], val);
        }
        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nExiting cleanly.\n");
    release_resources();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>
#include <errno.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdarg.h>
#include <pthread.h>
#include <mosquitto.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor_data"
#define MCP3008_CHANNEL 0
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define SAMPLE_INTERVAL_MS 1000

static volatile sig_atomic_t running = 1;
static int mq_client = -1;
static pthread_mutex_t mq_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char rx[3] = {0};

    int retries = 0;
    while (retries < MAX_RETRIES) {
        int ret = mosquitto_write(mq_client, tx, 3, false);
        if (ret != MOSQ_ERR_SUCCESS) {
            fprintf(stderr, "mosquitto_write failed: %s\n", mosquitto_strerror(ret));
            retries++;
            if (retries < MAX_RETRIES) {
                gpioDelay(RETRY_DELAY_MS * 1000);
            }
            continue;
        }

        gpioDelay(1000);

        int bytes_read = mosquitto_read(mq_client, rx, 3, 1000);
        if (bytes_read == 3) {
            int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
            return adc_value;
        }

        fprintf(stderr, "mosquitto_read failed: expected 3 bytes, got %d\n", bytes_read);
        retries++;
        if (retries < MAX_RETRIES) {
            gpioDelay(RETRY_DELAY_MS * 1000);
        }
    }

    fprintf(stderr, "Failed to read MCP3008 after %d retries\n", MAX_RETRIES);
    return -1;
}

static void publish_sensor_data(int adc_value) {
    pthread_mutex_lock(&mq_mutex);

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    char message[128];
    snprintf(message, sizeof(message), "%s, ADC Value: %d", timestamp, adc_value);

    int ret = mosquitto_publish(mq_client, NULL, MQTT_TOPIC, strlen(message), message, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "mosquitto_publish failed: %s\n", mosquitto_strerror(ret));
    }

    pthread_mutex_unlock(&mq_mutex);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    mq_client = mosquitto_new(NULL, true, NULL);
    if (!mq_client) {
        fprintf(stderr, "mosquitto_new failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int ret = mosquitto_connect(mq_client, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "mosquitto_connect failed: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mq_client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = mosquitto_loop_start(mq_client);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "mosquitto_loop_start failed: %s\n", mosquitto_strerror(ret));
        mosquitto_disconnect(mq_client);
        mosquitto_destroy(mq_client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting MCP3008 sensor data publishing...\n");

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            publish_sensor_data(adc_value);
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");

    mosquitto_loop_stop(mq_client, false);
    mosquitto_disconnect(mq_client);
    mosquitto_destroy(mq_client);
    gpioTerminate();

    pthread_mutex_destroy(&mq_mutex);

    printf("Program terminated successfully.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE "/dev/video0"
#define IMAGE_FILE "image.jpg"

int main(void) {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned char *buffer = NULL;
    int ret;

    fd = open(DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    memset(&cap, 0, sizeof(cap));
    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE);
        close(fd);
        return EXIT_FAILURE;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    ret = ioctl(fd, VIDIOC_S_FMT, &fmt);
    if (ret < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_JPEG) {
        fprintf(stderr, "Error: Unsupported pixel format: %c\n", fmt.fmt.pix.pixelformat);
        close(fd);
        return EXIT_FAILURE;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    ret = ioctl(fd, VIDIOC_REQBUFS, &req);
    if (ret < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(fd);
        return EXIT_FAILURE;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    ret = ioctl(fd, VIDIOC_QUERYBUF, &buf);
    if (ret < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    ret = ioctl(fd, VIDIOC_QBUF, &buf);
    if (ret < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        munmap(buffer, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ret = ioctl(fd, VIDIOC_STREAMON, &type);
    if (ret < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        munmap(buffer, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    fd_set fds;
    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = 5;
    tv.tv_usec = 0;

    ret = select(fd + 1, &fds, NULL, NULL, &tv);
    if (ret < 0) {
        fprintf(stderr, "Error during select: %s\n", strerror(errno));
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer, buf.length);
        close(fd);
        return EXIT_FAILURE;
    } else if (ret == 0) {
        fprintf(stderr, "Error: Timeout waiting for image capture\n");
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    ret = ioctl(fd, VIDIOC_DQBUF, &buf);
    if (ret < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(IMAGE_FILE, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", IMAGE_FILE, strerror(errno));
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    size_t written = fwrite(buffer, 1, buf.bytesused, fp);
    if (written != buf.bytesused) {
        fprintf(stderr, "Error writing to %s: %s\n", IMAGE_FILE, strerror(errno));
        fclose(fp);
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    fclose(fp);

    printf("Image saved to %s\n", IMAGE_FILE);

    ioctl(fd, VIDIOC_STREAMOFF, &type);
    munmap(buffer, buf.length);
    close(fd);

    return EXIT_SUCCESS;
}

