#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define PCF8574_ADDR 0x38

static volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    (void)sig;
    running = 0;
}

int main() {
    int fd;
    unsigned char buf[1];
    int val;

    // Set up signal handler for clean exit
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa, NULL);

    // Open I2C bus
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    // Set slave address
    if (ioctl(fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", PCF8574_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    // Main loop
    while (running) {
        // Read from PCF8574
        if (read(fd, buf, 1) != 1) {
            fprintf(stderr, "Failed to read from PCF8574: %s\n", strerror(errno));
            break;
        }

        // Display the value
        val = buf[0];
        printf("PCF8574 Value: %d\n", val);
        fflush(stdout);

        // Wait 0.5 seconds
        sleep(0.5);
    }

    // Cleanup
    close(fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

