#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define SHT31_ADDR 0x44
#define I2C_DEV "/dev/i2c-1"
#define MEASUREMENT_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sht31(int fd, float *temperature, float *humidity) {
    uint8_t cmd = 0x24;
    uint8_t data[6];

    if (i2c_write_byte(fd, cmd) < 0) {
        return -1;
    }

    usleep(10000);

    if (i2c_read_bytes(fd, data, 6) < 0) {
        return -1;
    }

    uint16_t raw_temperature = (data[0] << 8) | data[1];
    uint16_t raw_humidity = (data[3] << 8) | data[4];

    if ((raw_temperature & 0xFC00) == 0x0000) {
        return -2;
    }

    float temperature_c = -45.0f + (175.0f * (float)raw_temperature / 65535.0f);
    float humidity_rh = 100.0f * (float)raw_humidity / 65535.0f;

    if (humidity_rh < 0.0f || humidity_rh > 100.0f) {
        return -3;
    }

    *temperature = temperature_c;
    *humidity = humidity_rh;
    return 0;
}

int main(void) {
    int fd = -1;
    float temperature, humidity;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SHT31_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SHT31_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    while (running) {
        int result = read_sht31(fd, &temperature, &humidity);

        if (result == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else if (result == -2) {
            fprintf(stderr, "SHT31 measurement error: invalid temperature data\n");
        } else if (result == -3) {
            fprintf(stderr, "SHT31 measurement error: invalid humidity data\n");
        } else {
            fprintf(stderr, "SHT31 measurement error: %s\n", strerror(errno));
        }

        for (int i = 0; i < MEASUREMENT_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    if (fd >= 0) {
        close(fd);
    }

    printf("\nExiting cleanly.\n");
    return 0;
}

