        if (gpiod_line_request_input(lines[i], "gpio-control") < 0) {
            perror("gpiod_line_request_input");
            goto cleanup;
        }
    }

    printf("Monitoring GPIO 17, 22, 27 (BCM) every %d second(s).\n", POLL_INTERVAL_SEC);
    printf("Press Ctrl+C to exit.\n");

    while (keep_running) {
        int val17 = gpiod_line_get_value(lines[0]);
        int val22 = gpiod_line_get_value(lines[1]);
        int val27 = gpiod_line_get_value(lines[2]);

        if (val17 < 0 || val22 < 0 || val27 < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        printf("GPIO 17: %d, GPIO 22: %d, GPIO 27: %d\n", val17, val22, val27);
        fflush(stdout);

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nExiting cleanly.\n");
