#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN_OUTPUT 2
#define GPIO_PIN_INPUT 17
#define POLL_INTERVAL_SEC 60

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *output_line = NULL;
    struct gpiod_line *input_line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the output line */
    output_line = gpiod_chip_get_line(chip, GPIO_PIN_OUTPUT);
    if (!output_line) {
        perror("gpiod_chip_get_line (output)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the output line as output, initial value LOW */
    ret = gpiod_line_request_output(output_line, "gpio-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (output)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Get the input line */
    input_line = gpiod_chip_get_line(chip, GPIO_PIN_INPUT);
    if (!input_line) {
        perror("gpiod_chip_get_line (input)");
        gpiod_line_release(output_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the input line as input */
    ret = gpiod_line_request_input(input_line, "gpio-input");
    if (ret < 0) {
        perror("gpiod_line_request_input (input)");
        gpiod_line_release(output_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO output control started. Press Ctrl+C to exit.\n");

    /* Main loop: poll every POLL_INTERVAL_SEC seconds */
    while (keep_running) {
        int value = gpiod_line_get_value(input_line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            break;
        }
        printf("GPIO input value: %d\n", value);
        fflush(stdout);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    /* Clean up */
    printf("\nCleaning up...\n");
    gpiod_line_release(output_line);
    gpiod_line_release(input_line);
    gpiod_chip_close(chip);

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

