            perror("gpiod_line_set_value (line3)");
            cleanup();
            return EXIT_FAILURE;
        }
        printf("GPIO 1, 2, 3 HIGH\n");
        fflush(stdout);
        sleep(1);

        if (!keep_running) break;

        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("gpiod_line_set_value (line1)");
            cleanup();
            return EXIT_FAILURE;
        }
