static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_pixel(int gpio, int pixel, int r, int g, int b) {
    if (gpioWrite(gpio, (r << 16) | (g << 8) | b) < 0) {
        fprintf(stderr, "Error: gpioWrite failed on pixel %d\n", pixel);
        exit(EXIT_FAILURE);
    }
}

int main(void) {
