        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    for (int cycle = 0; cycle < 3 && running; cycle++) {
        for (int pixel = 0; pixel < NUM_PIXELS; pixel++) {
            set_pixel(GPIO_PIN, pixel, 255, 0, 0);
            usleep(CYCLE_DELAY_US);
            set_pixel(GPIO_PIN, pixel, 0, 255, 0);
            usleep(CYCLE_DELAY_US);
            set_pixel(GPIO_PIN, pixel, 0, 0, 255);
