#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define DS18B20_GPIO 4
#define MAX_READINGS 3
#define READ_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(float *temperature) {
    char path[64];
    char buf[256];
    FILE *fp;
    int retries = 3;

    snprintf(path, sizeof(path), "/sys/bus/w1/devices/28-%02X%02X%02X%02X%02X%02X%02X%02X/w1_slave",
             DS18B20_GPIO & 0x7F,
             (DS18B20_GPIO >> 8) & 0xFF,
             (DS18B20_GPIO >> 16) & 0xFF,
             (DS18B20_GPIO >> 24) & 0xFF,
             (DS18B20_GPIO >> 32) & 0xFF,
             (DS18B20_GPIO >> 40) & 0xFF,
             (DS18B20_GPIO >> 48) & 0xFF,
             (DS18B20_GPIO >> 56) & 0xFF);

    while (retries > 0) {
        fp = fopen(path, "r");
        if (fp == NULL) {
            fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
            retries--;
            if (retries > 0) {
                sleep(1);
            }
            continue;
        }

        if (fgets(buf, sizeof(buf), fp) == NULL) {
            fprintf(stderr, "Error reading from %s: %s\n", path, strerror(errno));
            fclose(fp);
            retries--;
            if (retries > 0) {
                sleep(1);
            }
            continue;
        }

        if (fclose(fp) != 0) {
            fprintf(stderr, "Error closing %s: %s\n", path, strerror(errno));
            retries--;
            if (retries > 0) {
                sleep(1);
            }
            continue;
        }

        if (strstr(buf, "YES") == NULL) {
            fprintf(stderr, "Device not present at %s\n", path);
            return -1;
        }

        char *temp_str = strstr(buf, "t=");
        if (temp_str == NULL) {
            fprintf(stderr, "Error parsing temperature from %s\n", path);
            return -1;
        }

        char *endptr;
        long raw = strtol(temp_str + 2, &endptr, 10);
        if (endptr == temp_str + 2 || *endptr != '\0') {
            fprintf(stderr, "Error converting temperature from %s\n", path);
            return -1;
        }

        *temperature = (float)raw / 1000.0f;
        return 0;
    }

    return -1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    printf("Starting temperature readings on GPIO %d every %d seconds. Press Ctrl+C to exit.\n",
           DS18B20_GPIO, READ_INTERVAL_SEC);

    while (running) {
        float temperature;
        int result = read_temperature(&temperature);

        if (result == 0) {
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature after multiple retries.\n");
        }

        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

