#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 4
#define PWM_PIN_2 17
#define PWM_PIN_3 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define PWM_DUTY_CYCLE 500

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN_1);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN_2);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN_3);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN_1);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN_2);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN_3);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN_1);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN_2);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN_3);
        gpioTerminate();
        return 1;
    }

    if (gpioPWM(PWM_PIN_1, PWM_DUTY_CYCLE) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", PWM_PIN_1);
        gpioTerminate();
        return 1;
    }
    if (gpioPWM(PWM_PIN_2, PWM_DUTY_CYCLE) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", PWM_PIN_2);
        gpioTerminate();
        return 1;
    }
    if (gpioPWM(PWM_PIN_3, PWM_DUTY_CYCLE) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", PWM_PIN_3);
        gpioTerminate();
        return 1;
    }

    printf("PWM duty cycle applied to GPIO %d, %d, %d\n", PWM_PIN_1, PWM_PIN_2, PWM_PIN_3);

    while (program_running) {
        sleep(1);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);

    gpioTerminate();
    printf("PWM duty cycle cleared and pigpio terminated.\n");

    return 0;
}

