#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define DHT22_TIMEOUT_US 100000
#define DHT22_CYCLE_COUNT 3

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read 40 bits from the DHT22.
 * Returns 0 on success, -1 on timeout, -2 on checksum error.
 */
static int read_dht22(struct gpiod_line *line, uint8_t *data) {
    uint8_t laststate = 1;
    uint8_t counter = 0;
    uint8_t j = 0;

    /* Send start signal: pull low for >=1ms, then high for 20-40us */
    if (gpiod_line_request_output(line, "dht22", 0) < 0) {
        fprintf(stderr, "Failed to request output line: %s\n", strerror(errno));
        return -1;
    }
    gpiod_line_set_value(line, 0);
    usleep(1000);
    gpiod_line_set_value(line, 1);
    usleep(30);

    /* Switch to input with pull-up */
    if (gpiod_line_request_input_flags(line, "dht22", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request input line: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for sensor response: low then high */
    int timeout = DHT22_TIMEOUT_US;
    while (gpiod_line_get_value(line) == 1) {
        if (--timeout <= 0) {
            fprintf(stderr, "DHT22 response timeout (sensor absent or not responding)\n");
            return -1;
        }
        usleep(1);
    }
    timeout = DHT22_TIMEOUT_US;
    while (gpiod_line_get_value(line) == 0) {
        if (--timeout <= 0) {
            fprintf(stderr, "DHT22 response timeout (sensor absent or not responding)\n");
            return -1;
        }
        usleep(1);
    }
    timeout = DHT22_TIMEOUT_US;
    while (gpiod_line_get_value(line) == 1) {
        if (--timeout <= 0) {
            fprintf(stderr, "DHT22 response timeout (sensor absent or not responding)\n");
            return -1;
        }
        usleep(1);
    }

    /* Read 40 data bits */
    for (int i = 0; i < 40; i++) {
        /* Wait for low-to-high transition */
        timeout = DHT22_TIMEOUT_US;
        while (gpiod_line_get_value(line) == 0) {
            if (--timeout <= 0) {
                fprintf(stderr, "DHT22 data timeout (bit %d)\n", i);
                return -1;
            }
            usleep(1);
        }

        /* Measure high duration: ~26-28us = '0', ~70us = '1' */
        timeout = DHT22_TIMEOUT_US;
        uint32_t start_tick = 0;
        while (gpiod_line_get_value(line) == 1) {
            if (--timeout <= 0) {
                fprintf(stderr, "DHT22 data timeout (bit %d)\n", i);
                return -1;
            }
            usleep(1);
        }
        uint32_t end_tick = 0;
        while (gpiod_line_get_value(line) == 0) {
            if (--timeout <= 0) {
                fprintf(stderr, "DHT22 data timeout (bit %d)\n", i);
                return -1;
            }
            usleep(1);
        }
        end_tick = gpiod_line_get_value_tick(line);

        uint32_t duration = end_tick - start_tick;
        if (duration > 50) {
            data[j / 8] |= (1 << (7 - (j % 8)));
        }
        j++;
    }

    /* Verify checksum */
    uint8_t checksum = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
    if (checksum != data[4]) {
        fprintf(stderr, "DHT22 checksum error: computed 0x%02X, received 0x%02X\n", checksum, data[4]);
        return -2;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open GPIO chip 0 (Raspberry Pi GPIO controller) */
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip 0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", DHT22_PIN, strerror(errno));
        goto cleanup;
    }

    printf("DHT22 sensor reader started on GPIO %d. Press Ctrl+C to exit.\n", DHT22_PIN);

    for (int cycle = 0; cycle < DHT22_CYCLE_COUNT && running; cycle++) {
        uint8_t data[5] = {0};
        int result = read_dht22(line, data);

        if (result == 0) {
            printf("Cycle %d: Temperature = %.1f C, Humidity = %.1f %%\n",
                   cycle + 1, (float)data[2] + (float)data[3] / 10.0f, (float)data[0] + (float)data[1] / 10.0f);
        } else if (result == -1) {
            fprintf(stderr, "Cycle %d: DHT22 read failed (timeout or sensor absent)\n", cycle + 1);
        } else {
            fprintf(stderr, "Cycle %d: DHT22 read failed (checksum error)\n", cycle + 1);
        }

        /* Wait 2 seconds between cycles (DHT22 needs >=1s between cycles) */
        if (cycle < DHT22_CYCLE_COUNT - 1) {
            sleep(2);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("\nExiting.\n");
    return ret;
}

