#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PINS 6
#define PWM_RANGE 255
#define PWM_FREQ 1000
#define PWM_PERIOD_US (1000000 / PWM_FREQ)

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_pwm_range(int pin, int range) {
    if (gpioSetPWMrange(pin, range) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d, %d) failed\n", pin, range);
        return -1;
    }
    return 0;
}

static int set_pwm_frequency(int pin, int freq) {
    if (gpioSetPWMfrequency(pin, freq) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d, %d) failed\n", pin, freq);
        return -1;
    }
    return 0;
}

static int set_pwm_dutycycle(int pin, int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(pin, duty) < 0) {
        fprintf(stderr, "Error: gpioPWM(%d, %d) failed\n", pin, duty);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    for (int i = 0; i < PWM_PINS; i++) {
        gpioPWM(i, 0);
        gpioSetMode(i, PI_INPUT);
    }
    gpioTerminate();
}

int main(void) {
    int pins[PWM_PINS] = {17, 18, 22, 23, 24, 25};

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < PWM_PINS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (set_pwm_range(pins[i], PWM_RANGE) < 0) {
            cleanup();
            return EXIT_FAILURE;
        }
        if (set_pwm_frequency(pins[i], PWM_FREQ) < 0) {
            cleanup();
            return EXIT_FAILURE;
        }
        if (set_pwm_dutycycle(pins[i], 0) < 0) {
            cleanup();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("PWM output on GPIO 17, 18, 22, 23, 24, 25 (BCM). Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < PWM_PINS; i++) {
            printf("GPIO %d: %d\n", pins[i], gpioGetPWMdutycycle(pins[i]));
        }
        printf("\n");
        fflush(stdout);
        sleep(0.05);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

