#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define DHT22_PIN_17 17
#define NUM_CYCLES 3
#define CYCLE_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read DHT22 data.
 * Returns 0 on success, -1 on timeout, -2 on checksum error.
 */
static int read_dht22(struct gpiod_line *line, uint8_t *data) {
    uint8_t laststate = 1;
    uint8_t counter = 0;
    uint8_t j = 0;

    /* Send start signal: pull low for 1ms, then high for 30us */
    if (gpiod_line_request_output(line, "dht22", 0) < 0) {
        fprintf(stderr, "Failed to request output line: %s\n", strerror(errno));
        return -1;
    }
    gpiod_line_set_value(line, 0);
    usleep(1000);
    gpiod_line_set_value(line, 1);
    usleep(30);

    /* Switch to input mode */
    if (gpiod_line_request_input(line, "dht22") < 0) {
        fprintf(stderr, "Failed to request input line: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for sensor response: low for ~80us, high for ~80us */
    int timeout = 0;
    while (gpiod_line_get_value(line) == 1) {
        if (++timeout > 100) {
            fprintf(stderr, "DHT22 response timeout (sensor absent or wiring fault)\n");
            return -1;
        }
        usleep(1);
    }
    timeout = 0;
    while (gpiod_line_get_value(line) == 0) {
        if (++timeout > 100) {
            fprintf(stderr, "DHT22 response timeout (sensor absent or wiring fault)\n");
            return -1;
        }
        usleep(1);
    }
    timeout = 0;
    while (gpiod_line_get_value(line) == 1) {
        if (++timeout > 100) {
            fprintf(stderr, "DHT22 response timeout (sensor absent or wiring fault)\n");
            return -1;
        }
        usleep(1);
    }

    /* Read 40 bits */
    for (int i = 0; i < 40; i++) {
        /* Wait for low to start bit */
        timeout = 0;
        while (gpiod_line_get_value(line) == 1) {
            if (++timeout > 100) {
                fprintf(stderr, "DHT22 data timeout (bit %d)\n", i);
                return -1;
            }
            usleep(1);
        }

        /* Measure high duration: ~26-28us = '0', ~70us = '1' */
        timeout = 0;
        while (gpiod_line_get_value(line) == 0) {
            if (++timeout > 100) {
                fprintf(stderr, "DHT22 data timeout (bit %d)\n", i);
                return -1;
            }
            usleep(1);
        }
        counter++;

        /* Measure low duration: ~80us = '0', ~80us = '1' */
        timeout = 0;
        while (gpiod_line_get_value(line) == 1) {
            if (++timeout > 100) {
                fprintf(stderr, "DHT22 data timeout (bit %d)\n", i);
                return -1;
            }
            usleep(1);
        }
        if (counter % 2 == 0) {
            data[j / 8] <<= 1;
            if (counter > 40) {
                data[j / 8] |= 1;
            }
            j++;
        }
    }

    /* Verify checksum */
    uint8_t checksum = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
    if (checksum != data[4]) {
        fprintf(stderr, "DHT22 checksum error: calculated 0x%02X, received 0x%02X\n", checksum, data[4]);
        return -2;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open GPIO chip 0 (Raspberry Pi GPIO controller) */
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip 0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get GPIO line for DHT22 on BCM 4 */
    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", DHT22_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Starting DHT22 readings every %d seconds. Press Ctrl+C to exit.\n", CYCLE_INTERVAL_SEC);

    for (int cycle = 0; cycle < NUM_CYCLES && running; cycle++) {
        uint8_t data[5] = {0};
        int result = read_dht22(line, data);

        if (result == 0) {
            printf("Cycle %d: Temperature = %.1f C, Humidity = %.1f %%\n",
                   cycle + 1, (float)data[2] / 10.0f, (float)data[0] / 10.0f);
        } else if (result == -1) {
            fprintf(stderr, "Cycle %d: DHT22 read failed (timeout or sensor absent)\n", cycle + 1);
        } else {
            fprintf(stderr, "Cycle %d: DHT22 read failed (checksum error)\n", cycle + 1);
        }

        /* Sleep for the cycle interval, but wake early on signal */
        for (int s = 0; s < CYCLE_INTERVAL_SEC && running; s++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("\nExiting.\n");
    return ret;
}

