#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define TRIGGER_PIN_OFFSET 0
#define ECHO_PIN_OFFSET 1

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int trigger_sensor(struct gpiod_line *trigger_line) {
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        fprintf(stderr, "Error: Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    usleep(2);
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        fprintf(stderr, "Error: Failed to set trigger high: %s\n", strerror(errno));
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        fprintf(stderr, "Error: Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_echo_pulse(struct gpiod_line *echo_line) {
    int val;
    int timeout = 0;

    while ((val = gpiod_line_get_value(echo_line)) < 0) {
        if (errno == EINTR) {
            if (!running) return -1;
            continue;
        }
        fprintf(stderr, "Error: Failed to read echo line: %s\n", strerror(errno));
        return -1;
    }

    while (val == 1) {
        if (!running) return -1;
        val = gpiod_line_get_value(echo_line);
        if (val < 0) {
            fprintf(stderr, "Error: Failed to read echo line: %s\n", strerror(errno));
            return -1;
        }
        timeout++;
        if (timeout > 100000) {
            fprintf(stderr, "Error: Echo timeout (sensor absent or not responding)\n");
            return -1;
        }
    }

    return timeout;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger_line = NULL;
    struct gpiod_line *echo_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to set SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN_OFFSET);
    if (!trigger_line) {
        fprintf(stderr, "Error: Failed to get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN_OFFSET);
    if (!echo_line) {
        fprintf(stderr, "Error: Failed to get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger_line, "hc-sr04-trigger", 0) < 0) {
        fprintf(stderr, "Error: Failed to request trigger line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(echo_line, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Error: Failed to request echo line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        if (trigger_sensor(trigger_line) < 0) {
            fprintf(stderr, "Error: Trigger sensor failed, retrying...\n");
            sleep(1);
            continue;
        }

        int pulse_width = read_echo_pulse(echo_line);
        if (pulse_width < 0) {
            fprintf(stderr, "Error: Echo read failed, retrying...\n");
            sleep(1);
            continue;
        }

        printf("Pulse width: %d us\n", pulse_width);
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trigger_line) gpiod_line_release(trigger_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (chip) gpiod_chip_close(chip);

    printf("Program terminated.\n");
    return ret;
}

