#include <string.h>

#define VEML7700_ADDR 0x10
#define VEML7700_REG_ALS_CONF 0x00
#define VEML7700_REG_ALS_DATA 0x01
#define VEML7700_REG_PS_CONF 0x02
#define VEML7700_REG_PS_DATA 0x03

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int veml7700_init(int fd) {
    if (i2c_write_reg8(fd, VEML7700_REG_ALS_CONF, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, VEML7700_REG_PS_CONF, 0x00) < 0) return -1;
    return 0;
}

static int veml7700_read_als(int fd, uint16_t *als) {
    uint8_t data[2];
    if (i2c_read_reg8(fd, VEML7700_REG_ALS_DATA, &data[0]) < 0) return -1;
    if (i2c_read_reg8(fd, VEML7700_REG_ALS_DATA + 1, &data[1]) < 0) return -1;
    *als = ((uint16_t)data[1] << 8) | data[0];
    return 0;
}

static int veml7700_read_ps(int fd, uint16_t *ps) {
    uint8_t data[2];
    if (i2c_read_reg8(fd, VEML7700_REG_PS_DATA, &data[0]) < 0) return -1;
    if (i2c_read_reg8(fd, VEML7700_REG_PS_DATA + 1, &data[1]) < 0) return -1;
    *ps = ((uint16_t)data[1] << 8) | data[0];
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        goto cleanup;
    }

    if (veml7700_init(fd) < 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        goto cleanup;
    }

    printf("VEML7700 initialized. Reading every 0.5 seconds. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t als = 0, ps = 0;

        if (veml7700_read_als(fd, &als) < 0) {
            fprintf(stderr, "Failed to read ALS data\n");
            goto cleanup;
        }
        if (veml7700_read_ps(fd, &ps) < 0) {
            fprintf(stderr, "Failed to read PS data\n");
            goto cleanup;
        }

        printf("ALS: %u, PS: %u\n", als, ps);
        fflush(stdout);

        sleep(0.5);
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

