    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);

    tty.c_lflag = 0;
    tty.c_oflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = setup_uart(UART_PORT);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    printf("UART initialized on %s at 115200 baud.\n", UART_PORT);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        char buffer[256];
        ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);

        if (bytes_read < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            break;
        }

        if (bytes_read == 0) {
            continue;
        }

        buffer[bytes_read] = '\0';
        printf("Received: %s\n", buffer);

        sleep(READ_INTERVAL_SEC);
    }

    printf("\nExiting...\n");
    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define SPEED_OF_SOUND 34300.0
#define TIMEOUT_US 500000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int trigger_sensor(struct gpiod_line *trigger) {
    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    usleep(2);
    if (gpiod_line_set_value(trigger, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high: %s\n", strerror(errno));
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_echo_pulse(struct gpiod_line *echo) {
    int start_tick = 0, end_tick = 0;
    int timeout = 0;

    /* Wait for echo to go high (start of pulse) */
    while (gpiod_line_get_value(echo) == 0) {
        if (++timeout > TIMEOUT_US) {
            fprintf(stderr, "Error: echo start timeout\n");
            return -1;
        }
        usleep(1);
    }
    start_tick = timeout;

    /* Wait for echo to go low (end of pulse) */
    timeout = 0;
    while (gpiod_line_get_value(echo) == 1) {
        if (++timeout > TIMEOUT_US) {
            fprintf(stderr, "Error: echo end timeout\n");
            return -1;
        }
        usleep(1);
    }
    end_tick = timeout;

    return end_tick - start_tick;
}

static double calculate_distance(int pulse_width_us) {
    return (double)pulse_width_us * SPEED_OF_SOUND / 2000000.0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL, *echo = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean exit */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get trigger line */
    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        fprintf(stderr, "Error: failed to get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    /* Get echo line */
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Error: failed to get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request trigger line as output, initial value low */
    if (gpiod_line_request_output(trigger, "hcsr04-trigger", 0) < 0) {
        fprintf(stderr, "Error: failed to request trigger line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request echo line as input */
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Error: failed to request echo line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        if (trigger_sensor(trigger) < 0) {
            fprintf(stderr, "Warning: trigger sensor failed, retrying...\n");
            sleep(1);
            continue;
        }

        int pulse_width = read_echo_pulse(echo);
        if (pulse_width < 0) {
            fprintf(stderr, "Warning: echo read failed, retrying...\n");
            sleep(1);
            continue;
        }

        double distance = calculate_distance(pulse_width);

        if (distance < 2.0 || distance > 400.0) {
            fprintf(stderr, "Warning: distance out of range (%.2f cm), skipping...\n", distance);
            sleep(1);
            continue;
        }

        printf("Distance: %.2f cm\n", distance);
        fflush(stdout);

        sleep(1);
    }

    printf("\nExiting cleanly...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure trigger is low before releasing */
    if (trigger) {
        gpiod_line_set_value(trigger, 0);
        gpiod_line_release(trigger);
    }
    if (echo) {
        gpiod_line_release(echo);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 8
#define CONSUMER "digital-output"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Digital output on GPIO %d (BCM) set to LOW. Press Ctrl+C to exit.\n", GPIO_LINE);

    /* Main loop: read and print state every 0.001 s */
    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }
        printf("GPIO %d: %d\n", GPIO_LINE, val);
        fflush(stdout);
        usleep(1000); /* 1 ms */
    }

    /* Clean up: release line and close chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_regs(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error setting I2C register pointer 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "Error reading %zu bytes from I2C register 0x%02X: %s\n", len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    int16_t x, y, z;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", ADXL345_ADDRESS, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (i2c_write_reg(fd, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t buf[6];
        if (i2c_read_regs(fd, ADXL345_REG_DATAX0, buf, 6) < 0) {
            break;
        }

        x = (int16_t)((buf[1] << 8) | buf[0]);
        y = (int16_t)((buf[3] << 8) | buf[2]);
        z = (int16_t)((buf[5] << 8) | buf[4]);

        printf("X: %6d, Y: %6d, Z: %6d\n", x, y, z);
        fflush(stdout);

        usleep(100000);
    }

    if (fd >= 0) {
        close(fd);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_PINS 8
#define CONSUMER "gpio-control"

static const unsigned int pins[NUM_PINS] = {4, 17, 18, 22, 23, 24, 25, 27};
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_PINS];
static volatile sig_atomic_t keep_running = 1;

static void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n", pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output: %s\n", pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    while (keep_running) {
        for (int i = 0; i < NUM_PINS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Failed to read GPIO line %u: %s\n", pins[i], strerror(errno));
                cleanup();
                return EXIT_FAILURE;
            }
            printf("GPIO %u: %d\n", pins[i], val);
        }
        fflush(stdout);
        sleep(0.05);
    }

    cleanup();
    return EXIT_SUCCESS;
}

