#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define SPEED_OF_SOUND 34300.0
#define TIMEOUT_US 30000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int trigger_sensor(struct gpiod_line *trigger) {
    if (gpiod_line_set_value(trigger, 0) < 0) {
        perror("Failed to set trigger low");
        return -1;
    }
    usleep(2);
    if (gpiod_line_set_value(trigger, 1) < 0) {
        perror("Failed to set trigger high");
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trigger, 0) < 0) {
        perror("Failed to set trigger low");
        return -1;
    }
    return 0;
}

static int read_echo_pin(struct gpiod_line *echo) {
    int val;
    int timeout = 0;
    do {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("Failed to read echo pin");
            return -1;
        }
        usleep(1);
        timeout++;
    } while (val == 1 && timeout < TIMEOUT_US);
    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1;
    }

    timeout = 0;
    do {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("Failed to read echo pin");
            return -1;
        }
        usleep(1);
        timeout++;
    } while (val == 0 && timeout < TIMEOUT_US);
    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1;
    }

    timeout = 0;
    long long start_time = 0;
    do {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("Failed to read echo pin");
            return -1;
        }
        if (val == 1) {
            start_time = (long long)timeout;
        }
        usleep(1);
        timeout++;
    } while (val == 1 && timeout < TIMEOUT_US);
    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1;
    }

    timeout = 0;
    long long end_time = 0;
    do {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("Failed to read echo pin");
            return -1;
        }
        if (val == 0) {
            end_time = (long long)timeout;
        }
        usleep(1);
        timeout++;
    } while (val == 0 && timeout < TIMEOUT_US);
    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1;
    }

    long long duration = end_time - start_time;
    double distance = (duration * SPEED_OF_SOUND) / 2000000.0;
    return (int)distance;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set SIGTERM handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        perror("Failed to get trigger line");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("Failed to get echo line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, "hc-sr04-trigger", 0) < 0) {
        perror("Failed to request trigger line as output");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("Failed to request echo line as input");
        goto cleanup;
    }

    printf("HC-SR04 sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        if (trigger_sensor(trigger) < 0) {
            fprintf(stderr, "Trigger failed, retrying...\n");
            usleep(100000);
            continue;
        }

        int distance = read_echo_pin(echo);
        if (distance < 0) {
            fprintf(stderr, "Echo read failed, retrying...\n");
            usleep(100000);
            continue;
        }

        if (distance < 0 || distance > 400) {
            fprintf(stderr, "Distance out of range: %d cm\n", distance);
        } else {
            printf("Distance: %d cm\n", distance);
        }

        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trigger) {
        gpiod_line_release(trigger);
    }
    if (echo) {
        gpiod_line_release(echo);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Program terminated.\n");
    return ret;
}

