#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 2
#define PWM_PIN_2 3
#define PWM_PIN_3 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define PWM_DUTY_CYCLE 500

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_pwm_pin(int pin, int duty_cycle) {
    if (gpioPWM(pin, duty_cycle) < 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", PWM_PIN_1);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", PWM_PIN_2);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_3, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", PWM_PIN_3);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for pin %d\n", PWM_PIN_1);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for pin %d\n", PWM_PIN_2);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for pin %d\n", PWM_PIN_3);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for pin %d\n", PWM_PIN_1);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for pin %d\n", PWM_PIN_2);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for pin %d\n", PWM_PIN_3);
        cleanup();
        return EXIT_FAILURE;
    }

    if (set_pwm_pin(PWM_PIN_1, PWM_DUTY_CYCLE) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    if (set_pwm_pin(PWM_PIN_2, PWM_DUTY_CYCLE) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    if (set_pwm_pin(PWM_PIN_3, PWM_DUTY_CYCLE) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("PWM output on GPIO %d, GPIO %d, GPIO %d set to %d/%d\n",
           PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_DUTY_CYCLE, PWM_RANGE);

    while (running) {
        sleep(5);
    }

    cleanup();
    printf("PWM output stopped, GPIOs released\n");
    return EXIT_SUCCESS;
}

