#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE_OUTPUT 3
#define GPIO_LINE_INPUT 5
#define CONSUMER "gpio-output"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *output_line = NULL;
    struct gpiod_line *input_line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the output line */
    output_line = gpiod_chip_get_line(chip, GPIO_LINE_OUTPUT);
    if (!output_line) {
        perror("gpiod_chip_get_line(output)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the output line as output, initial value LOW */
    ret = gpiod_line_request_output(output_line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(output)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Get the input line */
    input_line = gpiod_chip_get_line(chip, GPIO_LINE_INPUT);
    if (!input_line) {
        perror("gpiod_chip_get_line(input)");
        gpiod_line_release(output_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the input line as input */
    ret = gpiod_line_request_input(input_line, CONSUMER);
    if (ret < 0) {
        perror("gpiod_line_request_input(input)");
        gpiod_line_release(output_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO output control started. Press Ctrl+C to exit.\n");

    /* Main loop: report state every second until interrupted */
    while (keep_running) {
        int value = gpiod_line_get_value(input_line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            break;
        }
        printf("GPIO %d: %d\n", GPIO_LINE_INPUT, value);
        fflush(stdout);
        sleep(1);
    }

    /* Clean up */
    gpiod_line_release(output_line);
    gpiod_line_release(input_line);
    gpiod_chip_close(chip);

    printf("\nGPIO output control stopped.\n");
    return EXIT_SUCCESS;
