#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 18
#define ECHO_PIN 23
#define SPEED_OF_SOUND 34300.0
#define TIMEOUT_US 30000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int trigger_sensor(struct gpiod_line *trigger) {
    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Error: Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    usleep(2);
    if (gpiod_line_set_value(trigger, 1) < 0) {
        fprintf(stderr, "Error: Failed to set trigger high: %s\n", strerror(errno));
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Error: Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_echo_pin(struct gpiod_line *echo) {
    int val;
    int timeout = 0;

    while (gpiod_line_get_value(echo) == 0) {
        usleep(1);
        timeout++;
        if (timeout > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pin stuck low (timeout)\n");
            return -1;
        }
    }

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (gpiod_line_get_value(echo) == 1) {
        usleep(1);
        timeout++;
        if (timeout > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pin stuck high (timeout)\n");
            return -1;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    long long duration = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
    double distance = (duration / 2.0) / 1000000.0 * SPEED_OF_SOUND / 2.0;

    if (distance < 2.0 || distance > 400.0) {
        fprintf(stderr, "Error: Distance out of range: %.2f cm\n", distance);
        return -1;
    }

    return (int)distance;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to set SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        fprintf(stderr, "Error: Failed to get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Error: Failed to get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, "hc-sr04-trigger", 0) < 0) {
        fprintf(stderr, "Error: Failed to request trigger line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Error: Failed to request echo line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 distance sensor started. Press Ctrl+C to exit.\n");

    while (running) {
        if (trigger_sensor(trigger) < 0) {
            fprintf(stderr, "Error: Trigger sensor failed\n");
            break;
        }

        int distance = read_echo_pin(echo);
        if (distance < 0) {
            fprintf(stderr, "Error: Echo read failed\n");
            break;
        }

        printf("Distance: %d cm\n", distance);
        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trigger) {
        gpiod_line_release(trigger);
    }
    if (echo) {
        gpiod_line_release(echo);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

