#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE_17 17
#define GPIO_LINE_18 18

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line17 = NULL;
static struct gpiod_line *line18 = NULL;
static volatile sig_atomic_t keep_running = 1;

static void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

static void cleanup(void) {
    if (line17) {
        gpiod_line_release(line17);
        line17 = NULL;
    }
    if (line18) {
        gpiod_line_release(line18);
        line18 = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_LINE_17);
    if (!line17) {
        perror("gpiod_chip_get_line(17)");
        cleanup();
        return EXIT_FAILURE;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_LINE_18);
    if (!line18) {
        perror("gpiod_chip_get_line(18)");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line17, "gpio-control", 0) < 0) {
        perror("gpiod_line_request_output(17)");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line18, "gpio-control", 0) < 0) {
        perror("gpiod_line_request_output(18)");
        cleanup();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int val17 = gpiod_line_get_value(line17);
        int val18 = gpiod_line_get_value(line18);

        if (val17 < 0 || val18 < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        if (val17 != 0 && val17 != 1) {
            fprintf(stderr, "Warning: invalid value for GPIO 17 (%d). Setting to 0.\n", val17);
            val17 = 0;
            if (gpiod_line_set_value(line17, val17) < 0) {
                perror("gpiod_line_set_value(17)");
                break;
            }
        }

        if (val18 != 0 && val18 != 1) {
            fprintf(stderr, "Warning: invalid value for GPIO 18 (%d). Setting to 0.\n", val18);
            val18 = 0;
            if (gpiod_line_set_value(line18, val18) < 0) {
                perror("gpiod_line_set_value(18)");
                break;
            }
        }

        printf("GPIO 17: %d, GPIO 18: %d\n", val17, val18);
        fflush(stdout);

        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

